changed=[]
for relative,replacements in changes.items():
 p=root/relative; raw=p.read_bytes(); text=raw.decode(); nl='\r\n' if '\r\n' in text else '\n'; normalized=text.replace('\r\n','\n')
 for old,new in replacements:
  old=old.replace('\r\n','\n'); new=new.replace('\r\n','\n')
  assert normalized.count(old)==1,(relative,old[:110])
  normalized=normalized.replace(old,new)
 p.write_bytes(normalized.replace('\n',nl).encode()); changed.append(relative)
print('\n'.join(changed))
